import { File, Paths } from 'expo-file-system';
import { gzipSync } from 'fflate';

import { newId } from '@stxapps/expo-crypto/lib/ids';
import { newFacet, readerDocSchema, utf8 } from '@stxapps/shared';

import { writeExtraction, writeFile } from './mutations';

// Store the read-mode copy a Safari share carried — the iOS share extension's
// preprocessing ran the converter inside the shared page (share-extension/
// preprocessing.js, generated by tools/scripts/generate-reader-capture.ts), and the
// draft brought its `ReaderDoc` across. Called by drainShareOutbox in the APP'S
// process only, after the draft's link has landed, and only when the caller has
// decided the account keeps it — the plan's `keptCopies` and the synced save setting
// (`keepOnSaveOf`) both say yes. The share extension never calls this: its process
// can't open the store, and the plan and settings are the app's to judge.
// docs/link-extraction-keep.md, _expo_.
//
// The copy came from a LIVE page, in the user's own Safari session, so it is written
// at the active-page tier (`expo:fg`) — the same tier the browser extension's
// active-tab capture has. It is re-validated against `readerDocSchema` here: the draft
// file is the share extension's output, read back off the App Group container.
//
// Returns whether a copy was written. Never throws: a copy that can't be stored costs
// the link its copy, never the drain the rest of the outbox.
const tempFileFor = (id: string) => new File(Paths.cache, `share-read-mode-${id}.gz`);

export async function applyShareReadMode(
  username: string,
  linkId: string,
  readMode: unknown,
): Promise<boolean> {
  const parsed = readerDocSchema.safeParse(readMode);
  if (!parsed.success) return false;

  const fileId = newId();
  const temp = tempFileFor(fileId);
  try {
    temp.write(gzipSync(utf8(JSON.stringify(parsed.data))));
    await writeFile(username, fileId, temp); // content before metadata
    await writeExtraction(username, linkId, {
      fields: { readModeId: fileId },
      facet: 'readMode',
      state: newFacet('done', 'expo:fg'),
    });
    return true;
  } catch {
    return false;
  } finally {
    try {
      if (temp.exists) temp.delete();
    } catch {
      // A leftover in the cache directory is the OS's to reclaim.
    }
  }
}
